In C++, you can create a linked list by defining a structure that contains a data element and a pointer to the next element in the list. Here is an example of how to create a simple singly linked list:

```cpp
#include <iostream>

using namespace std;

// Define the Node structure
struct Node {
    int data; // Data element
    Node* next; // Pointer to next node
};

// Function to create a new Node
Node* newNode(int data) {
    Node* node = new Node();
    if (!node) {
        cout << "Memory error\n";
        return NULL;
    }
    node->data = data;
    node->next = NULL;
    return node;
}

// Function to insert a new Node at the end
Node* insertAtEnd(Node* head, int data) {
    Node* newNode = newNode(data);
    if (head == NULL) {
        head = newNode;
        return head;
    }
    Node* last = head;
    while (last->next != NULL)
        last = last->next;
    last->next = newNode;
    return head;
}

// Function to print the list
void printList(Node* node) {
    while (node != NULL) {
        cout << node->data << " ";
        node = node->next;
    }
    cout << "\n";
}

